function slugify(title) {
  // Return empty string for non-string or missing input
  if (typeof title !== 'string') {
    return '';
  }

  return title
    .trim()
    .toLowerCase()
    .replace(/[\s_]+/g, '-')
    .replace(/[^a-z0-9-]/g, '')
    .replace(/-+/g, '-')
    .replace(/^-+|-+$/g, '');
}

module.exports = { slugify };

const test = require('node:test');
const assert = require('node:assert/strict');
const { slugify } = require('./slugify');

test('slugify converts title to URL-friendly slug', () => {
  assert.strictEqual(slugify('Hello World'), 'hello-world');
});

test('slugify strips punctuation and special characters', () => {
  assert.strictEqual(slugify('Hello, World! @#$%'), 'hello-world');
});

test('slugify collapses multiple separators', () => {
  assert.strictEqual(slugify('hello___world   test'), 'hello-world-test');
});

test('slugify trims leading and trailing whitespace', () => {
  assert.strictEqual(slugify('  hello world  '), 'hello-world');
});

test('slugify handles empty string', () => {
  assert.strictEqual(slugify(''), '');
});

test('slugify handles non-string input', () => {
  assert.strictEqual(slugify(null), '');
  assert.strictEqual(slugify(undefined), '');
  assert.strictEqual(slugify(123), '');
});

test('slugify removes leading and trailing hyphens', () => {
  assert.strictEqual(slugify('---hello-world---'), 'hello-world');
});

function truncate(text, n) {
  // Convert non-string inputs to string; treat null/undefined as empty
  if (text == null) {
    text = '';
  } else if (typeof text !== 'string') {
    text = String(text);
  }

  // Handle edge cases for n
  if (n <= 0) {
    return '';
  }

  // No truncation needed
  if (text.length <= n) {
    return text;
  }

  // For very small n, return truncated ellipsis or as much as fits
  const ellipsis = '...';
  if (n <= ellipsis.length) {
    return ellipsis.slice(0, n);
  }

  // Normal truncation: text up to (n - 3) chars + ellipsis
  return text.slice(0, n - ellipsis.length) + ellipsis;
}

module.exports = { truncate };

const test = require('node:test');
const assert = require('node:assert/strict');
const { truncate } = require('./truncate');

test('returns text unchanged when length is less than n', () => {
  assert.equal(truncate('hello', 10), 'hello');
});

test('returns text unchanged when length equals n', () => {
  assert.equal(truncate('hello', 5), 'hello');
});

test('truncates text to exactly n characters with ellipsis', () => {
  const result = truncate('hello world', 8);
  assert.equal(result, 'hello...');
  assert.equal(result.length, 8);
});

test('truncates long text correctly', () => {
  const result = truncate('the quick brown fox jumps over the lazy dog', 20);
  assert.equal(result, 'the quick brown f...');
  assert.equal(result.length, 20);
});

test('handles n equal to ellipsis length (3)', () => {
  const result = truncate('hello world', 3);
  assert.equal(result, '...');
  assert.equal(result.length, 3);
});

test('handles n = 2', () => {
  const result = truncate('hello', 2);
  assert.equal(result, '..');
  assert.equal(result.length, 2);
});

test('handles n = 1', () => {
  const result = truncate('hello', 1);
  assert.equal(result, '.');
  assert.equal(result.length, 1);
});

test('handles n = 0', () => {
  assert.equal(truncate('hello', 0), '');
});

test('handles negative n', () => {
  assert.equal(truncate('hello', -5), '');
});

test('handles empty string', () => {
  assert.equal(truncate('', 10), '');
  assert.equal(truncate('', 0), '');
});

test('handles null input', () => {
  assert.equal(truncate(null, 10), '');
});

test('handles undefined input', () => {
  assert.equal(truncate(undefined, 10), '');
});

test('converts number to string', () => {
  assert.equal(truncate(12345, 3), '...');
  assert.equal(truncate(42, 10), '42');
});

